BEGIN; DO $$ BEGIN IF to_regprocedure('public.can_manage_accounting_debt()') IS NULL THEN RAISE EXCEPTION 'Thieu hang rao quyen cong no can_manage_accounting_debt(). Dung lai de kiem tra schema.'; END IF; END $$; CREATE OR REPLACE FUNCTION public.sales_debt_reconciliation_report_v1(p_customer_id uuid,p_start_date date,p_end_date date) RETURNS TABLE(row_id uuid,delivery_date date,shipment_no text,delivery_point_code text,delivery_point_name text,product_name text,internal_code text,sap_code text,unit_price numeric,delivered_qty numeric,line_total numeric,price_source text,entity_id uuid,entity_code text,entity_name text) LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public,pg_temp AS $$ DECLARE v_parent_customer_id uuid; BEGIN IF auth.uid() IS NULL OR NOT public.can_manage_accounting_debt() THEN RAISE EXCEPTION 'Chi Ke toan hoac Admin duoc xem bang ke doi chieu cong no ban hang.' USING ERRCODE='42501'; END IF; IF p_customer_id IS NULL OR p_start_date IS NULL OR p_end_date IS NULL THEN RAISE EXCEPTION 'Chua chon du khach hang va khoang ngay.'; END IF; IF p_start_date>p_end_date THEN RAISE EXCEPTION 'Tu ngay phai nho hon hoac bang Toi ngay.'; END IF; SELECT COALESCE(c.parent_customer_id,c.id) INTO v_parent_customer_id FROM public.customers c WHERE c.id=p_customer_id AND c.deleted_at IS NULL; IF v_parent_customer_id IS NULL THEN RAISE EXCEPTION 'Khong tim thay khach hang can doi chieu.'; END IF; RETURN QUERY WITH base_lines AS (SELECT t.id AS base_id,t.product_id,COALESCE(t.customer_id,dp.customer_id) AS billing_customer_id,COALESCE(t.delivery_customer_id,dp.delivery_customer_id) AS delivery_customer_id,t.qty AS base_qty,t.unit_cost AS saved_price,t.product_name_snapshot,t.product_spec_snapshot,t.shipment_line_no,COALESCE(s.shipment_date,t.tx_date::date) AS report_date,s.shipment_no,s.entity_id AS shipment_entity_id FROM public.inventory_transactions t LEFT JOIN public.delivery_plans dp ON dp.id=t.delivery_plan_id LEFT JOIN public.shipment_logs s ON s.id=t.shipment_id LEFT JOIN public.customers bc ON bc.id=COALESCE(t.customer_id,dp.customer_id) WHERE t.tx_type='out' AND t.adjusted_from_transaction_id IS NULL AND t.delivery_plan_id IS NOT NULL AND t.deleted_at IS NULL AND (t.shipment_id IS NULL OR (s.id IS NOT NULL AND s.deleted_at IS NULL)) AND COALESCE(s.shipment_date,t.tx_date::date)>=p_start_date AND COALESCE(s.shipment_date,t.tx_date::date)<=p_end_date AND COALESCE(bc.parent_customer_id,bc.id,t.customer_id,dp.customer_id)=v_parent_customer_id), effective_lines AS (SELECT b.*,b.base_qty+COALESCE((SELECT sum(CASE WHEN a.tx_type='adjust_in' THEN a.qty WHEN a.tx_type='adjust_out' THEN -a.qty ELSE 0 END) FROM public.inventory_transactions a WHERE a.adjusted_from_transaction_id=b.base_id AND a.deleted_at IS NULL AND a.tx_type IN ('adjust_in','adjust_out')),0) AS effective_qty FROM base_lines b) SELECT e.base_id,e.report_date,COALESCE(e.shipment_no,'Xuat nhanh'),COALESCE(dc.code,bc.code,pc.code,''),COALESCE(dc.name,bc.name,pc.name,''),COALESCE(NULLIF(e.product_name_snapshot,''),p.name,''),COALESCE(p.sku,''),COALESCE(p.sap_code,''),CASE WHEN e.saved_price>0 THEN e.saved_price ELSE NULL END,e.effective_qty,CASE WHEN e.saved_price>0 THEN e.effective_qty*e.saved_price ELSE NULL END,CASE WHEN e.saved_price>0 THEN 'saved' ELSE 'missing' END,COALESCE(e.shipment_entity_id,pc.selling_entity_id,bc.selling_entity_id),COALESCE(se.code,''),COALESCE(se.name,se.header_text,'Chua gan phap nhan') FROM effective_lines e LEFT JOIN public.products p ON p.id=e.product_id LEFT JOIN public.customers bc ON bc.id=e.billing_customer_id LEFT JOIN public.customers pc ON pc.id=v_parent_customer_id LEFT JOIN public.customers dc ON dc.id=e.delivery_customer_id LEFT JOIN public.selling_entities se ON se.id=COALESCE(e.shipment_entity_id,pc.selling_entity_id,bc.selling_entity_id) WHERE e.effective_qty>0 ORDER BY e.report_date,COALESCE(e.shipment_no,''),COALESCE(e.shipment_line_no,2147483647),COALESCE(p.sku,''),e.base_id; END; $$; REVOKE ALL ON FUNCTION public.sales_debt_reconciliation_report_v1(uuid,date,date) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.sales_debt_reconciliation_report_v1(uuid,date,date) TO authenticated; NOTIFY pgrst,'reload schema'; COMMIT;
